#!/usr/bin/env node
// Builds src/common/dune/arrakisTerrain.ts from the Dune mockup (data/board.js, data/board-overrides.js, data/worm-line.js).
// Why: the Shai-Hulud module needs the terrain of every Arrakis space (rock stops the worm) and the worm border around
// the polar sink. The mockup is the source; never edit the generated file by hand – change the mockup and run:
//   node scripts/make-arrakis-terrain.js <path to the mockup folder _outputs/terraforming-dune>
const fs = require('fs');
const path = require('path');
const vm = require('vm');

const mockup = process.argv[2];
if (mockup === undefined) {
  throw new Error('usage: node scripts/make-arrakis-terrain.js <mockup folder>');
}
const context = {window: {}};
for (const file of ['board.js', 'board-overrides.js', 'worm-line.js']) {
  vm.runInNewContext(fs.readFileSync(path.join(mockup, 'data', file), 'utf8'), context);
}
const board = context.window.DUNE_BOARD;
const overrides = context.window.DUNE_BOARD_OVERRIDES;
const cells = board.cells.map((cell, index) => ({...cell, ...(overrides[index] ?? {})}));

// Same test as the mockup (assets/page-board.js): a space lies behind the worm border when at least 40 % of its hexagon
// is inside the line around the polar sink
const hexWidth = board.hexWidth;
const hexHeight = hexWidth * 2 / Math.sqrt(3);
const line = context.window.DUNE_WORM_LINE.map(([x, y]) => [x - board.offsetX, y - board.offsetY]);
const insideLine = (x, y) => line.reduce((inside, [ax, ay], index) => {
  const [bx, by] = line[(index + line.length - 1) % line.length];
  return (ay > y) !== (by > y) && x < (bx - ax) * (y - ay) / (by - ay) + ax ? !inside : inside;
}, false);
const shareInside = (cell) => {
  let inHex = 0;
  let inLine = 0;
  for (let row = 0; row < 16; row++) {
    for (let column = 0; column < 16; column++) {
      const dx = (column / 15 - 0.5) * hexWidth;
      const dy = (row / 15 - 0.5) * hexHeight;
      if (Math.abs(dx) > hexWidth / 2 || Math.abs(dy) > hexHeight / 2 - Math.abs(dx) / Math.sqrt(3)) {
        continue;
      }
      inHex++;
      if (insideLine(cell.x + dx, cell.y + dy)) {
        inLine++;
      }
    }
  }
  return inLine / inHex;
};

// Space ids of the Mars boards start at 03 and run row by row, like the cells of the mockup
const spaceId = (index) => String(index + 3).padStart(2, '0');
const ZONE = {O: 'spicefield', B: 'basin', W: 'rock', D: 'erg', A: 'city', P: 'ice'};
const zones = Object.fromEntries(cells.map((cell, index) => [spaceId(index), ZONE[cell.zone] ?? 'erg']));
const behindBorder = cells.map((cell, index) => [spaceId(index), shareInside(cell)]).filter(([, share]) => share >= 0.4).map(([id]) => id);

const output = `// GENERATED by scripts/make-arrakis-terrain.js from the Dune mockup – do not edit by hand.
// Terrain of every Arrakis space (ArrakisBoard.ts) and the spaces behind the worm border around the polar sink.

export type ArrakisZone = 'spicefield' | 'basin' | 'rock' | 'erg' | 'city' | 'ice';

export const ARRAKIS_ZONES: Readonly<Record<string, ArrakisZone>> = ${JSON.stringify(zones, null, 2).replace(/"([^"]+)":/g, '\'$1\':').replace(/"/g, '\'').replace(/\n}$/, ',\n}')};

/** Spaces behind the worm border (polar sink): the worm never enters them */
export const BEHIND_WORM_BORDER: ReadonlyArray<string> = ${JSON.stringify(behindBorder).replace(/"/g, '\'').replace(/,/g, ', ')};
`;
fs.writeFileSync(path.join(__dirname, '..', 'src/common/dune/arrakisTerrain.ts'), output);
console.log('zones', cells.length, 'behind border', behindBorder.join(' '));
